def _cell(cell_type: str, source: str, tag: str):
    cell = {
        "cell_type": cell_type,
        "id": tag,
        "metadata": {"tags": [tag]},
        "source": source.strip() + "\n",
    }
    if cell_type == "code":
        cell.update({"execution_count": None, "outputs": []})
    return cell


def _find_cell(notebook: dict, cell_id: str) -> dict:
    matches = [cell for cell in notebook["cells"] if cell.get("id") == cell_id]
    if len(matches) != 1:
        raise ValueError(
            f"expected exactly one cell with id {cell_id!r}, found {len(matches)}"
        )
    return matches[0]


def _set_source(notebook: dict, cell_id: str, source: str) -> None:
    cell = _find_cell(notebook, cell_id)
    cell["source"] = source.strip() + "\n"
    if cell["cell_type"] == "code":
        cell["execution_count"] = None
        cell["outputs"] = []


def _clear_code_output(notebook: dict, cell_id: str) -> None:
    cell = _find_cell(notebook, cell_id)
    if cell["cell_type"] != "code":
        raise ValueError(f"cell {cell_id!r} is not code")
    cell["execution_count"] = None
    cell["outputs"] = []
    cell.setdefault("metadata", {}).pop("execution", None)


def _validate_unique_cell_ids(cells: list[dict], *, label: str) -> None:
    seen: set[str] = set()
    duplicates: set[str] = set()
    for cell in cells:
        cell_id = cell.get("id")
        if not isinstance(cell_id, str) or not cell_id:
            raise ValueError(f"{label} contains a cell without a non-empty string id")
        if cell_id in seen:
            duplicates.add(cell_id)
        seen.add(cell_id)
    if duplicates:
        formatted = ", ".join(repr(cell_id) for cell_id in sorted(duplicates))
        raise ValueError(f"{label} contains duplicate cell id(s): {formatted}")


def _validate_stage20_cells(
    notebook_cells: list[dict], replacement_cells: list[dict]
) -> None:
    """Validate the complete Stage 20 namespace before modifying the notebook."""
    _validate_unique_cell_ids(notebook_cells, label="source notebook")
    _validate_unique_cell_ids(replacement_cells, label="generated Stage 20 cells")

    generated_tags_by_id = {
        cell["id"]: frozenset({cell["id"]}) for cell in replacement_cells
    }
    overlap = set(generated_tags_by_id) & set(PRESERVED_STAGE20_TAGS_BY_ID)
    if overlap:
        formatted = ", ".join(repr(cell_id) for cell_id in sorted(overlap))
        raise ValueError(
            f"generated and preserved Stage 20 cell ids overlap: {formatted}"
        )
    allowed_tags_by_id = {
        **generated_tags_by_id,
        **PRESERVED_STAGE20_TAGS_BY_ID,
    }

    for cell in notebook_cells:
        cell_id = cell["id"]
        tags = cell.get("metadata", {}).get("tags", [])
        if not isinstance(tags, list):
            raise ValueError(f"cell {cell_id!r} metadata.tags must be a list")
        prefixed_tags = frozenset(
            tag
            for tag in tags
            if isinstance(tag, str) and tag.startswith(STAGE_TAG_PREFIX)
        )
        has_prefixed_id = cell_id.startswith(STAGE_TAG_PREFIX)
        if not has_prefixed_id and not prefixed_tags:
            continue
        if cell_id not in allowed_tags_by_id:
            raise ValueError(f"unknown {STAGE_TAG_PREFIX!r}-prefixed cell {cell_id!r}")
        expected_tags = allowed_tags_by_id[cell_id]
        if prefixed_tags != expected_tags:
            raise ValueError(
                f"cell {cell_id!r} has Stage 20 tags {sorted(prefixed_tags)!r}; "
                f"expected {sorted(expected_tags)!r}"
            )


